import * as React from "react";
import { graphql, type HeadFC } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestInlineForm } from "../components/auditRequestModal";
import juanPabloPortrait from "../images/contact/juanpablo.jpg";

function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

export default function ContactPage() {
  const { t } = useTranslation();

  const trustItems = (t("contact.trustItems", { returnObjects: true }) as string[]) || [];
  const heroItems = (t("contactPage.hero.items", { returnObjects: true }) as string[]) || [];
  const fitItems = (t("contactPage.sections.fit.items", { returnObjects: true }) as string[]) || [];

  return (
    <Layout data={info}>
      <main>

        {/* ======================================================
            HERO
        ====================================================== */}
        <section className="pf-hero shell">
          <div className="pf-hero-grid">

            <div className="pf-hero-meta">
              <div className="eyebrow">§ 01 · {t("contactPage.hero.kicker")}</div>
              <div className="mono muted" style={{ marginTop: "12px" }}>
                Montréal (ET) · EN / FR / ES
              </div>
            </div>

            <h1
              className="display-xl pf-title reveal"
              aria-label={t("contactPage.hero.title") as string}
            >
              {t("contactPage.hero.title")}
            </h1>

            <p className="body-lg pf-intro reveal">{t("contactPage.hero.desc")}</p>

            <div className="reveal" style={{ display: "flex", flexWrap: "wrap", gap: "8px", paddingTop: "4px" }}>
              {trustItems.map((item) => (
                <span key={item} className="tag mono">{item}</span>
              ))}
            </div>

          </div>
        </section>

        {/* ======================================================
            FORM + PORTRAIT
        ====================================================== */}
        <section className="shell" style={{ paddingBottom: "60px" }}>
          <header className="sec-head">
            <div className="eyebrow">§ 02 · {t("contactPage.sections.form.title")}</div>
            <h2 className="display-l reveal">{t("contactPage.sections.form.title")}</h2>
            <p className="body-lg reveal">{t("contactPage.sections.form.desc")}</p>
          </header>

          <div style={{
            display: "grid",
            gridTemplateColumns: "1fr 340px",
            gap: "24px",
            alignItems: "start",
          }}
            className="contact-grid"
          >
            {/* Form */}
            <div style={{
              border: "1px solid var(--rule)",
              borderRadius: "20px",
              overflow: "hidden",
              background: "var(--bg-2)",
            }}>
              <AuditRequestInlineForm
                serviceName={t("contact.auditService") as string}
                source="contact.page.inline"
              />
            </div>

            {/* Portrait + info */}
            <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
              <div style={{
                borderRadius: "18px",
                overflow: "hidden",
                border: "1px solid var(--rule)",
                aspectRatio: "4/5",
              }}>
                <img
                  src={juanPabloPortrait}
                  alt="Juan Pablo Riano"
                  width={640}
                  height={800}
                  style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center 18%", display: "block" }}
                  decoding="async"
                />
              </div>

              <div className="avail-card">
                <div className="eyebrow" style={{ marginBottom: "16px" }}>
                  § {t("contact.title").split(" ").slice(0, 3).join(" ")}
                </div>
                <ul style={{ display: "flex", flexDirection: "column", gap: "10px", position: "relative", zIndex: 1 }}>
                  {heroItems.map((item) => (
                    <li key={item} className="body" style={{ fontSize: "13px", margin: 0 }}>{item}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </section>

        {/* ======================================================
            DIRECT CONTACT
        ====================================================== */}
        <section className="who shell">
          <header className="sec-head">
            <div className="eyebrow">§ 03 · {t("contactPage.sections.direct.title")}</div>
            <h2 className="display-l reveal">{t("contactPage.sections.direct.title")}</h2>
            <p className="body-lg reveal">{t("contactPage.sections.direct.desc")}</p>
          </header>

          <div className="who-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
            <a
              href={info.whatsapp}
              target="_blank"
              rel="noreferrer"
              className="who-card tilt reveal"
              style={{ display: "block" }}
            >
              <div className="tilt-inner">
                <div className="mono muted" style={{ fontSize: "11px", letterSpacing: "0.12em", marginBottom: "12px" }}>
                  WhatsApp
                </div>
                <h3 className="display-s" style={{ fontSize: "clamp(18px, 1.6vw, 22px)", marginBottom: "12px" }}>
                  {t("contactPage.sections.direct.cards.whatsapp.title")}
                </h3>
                <p className="body" style={{ fontSize: "14px" }}>
                  {t("contactPage.sections.direct.cards.whatsapp.desc")}
                </p>
                <div style={{ marginTop: "24px" }}>
                  <span className="btn btn-dark" style={{ display: "inline-flex" }}>
                    {t("contact.secondary")} <ArrowIcon />
                  </span>
                </div>
              </div>
            </a>

            <a
              href={`mailto:${info.email}`}
              className="who-card tilt reveal"
              style={{ display: "block" }}
            >
              <div className="tilt-inner">
                <div className="mono muted" style={{ fontSize: "11px", letterSpacing: "0.12em", marginBottom: "12px" }}>
                  Email
                </div>
                <h3 className="display-s" style={{ fontSize: "clamp(18px, 1.6vw, 22px)", marginBottom: "12px" }}>
                  {t("contactPage.sections.direct.cards.email.title")}
                </h3>
                <p className="body" style={{ fontSize: "14px" }}>
                  {t("contactPage.sections.direct.cards.email.desc")}
                </p>
                <div style={{ marginTop: "24px" }}>
                  <span className="btn btn-ghost" style={{ display: "inline-flex" }}>
                    {t("contact.tertiary")} <ArrowIcon />
                  </span>
                </div>
              </div>
            </a>

            <a
              href={info.linkedIn}
              target="_blank"
              rel="noreferrer"
              className="who-card tilt reveal"
              style={{ display: "block" }}
            >
              <div className="tilt-inner">
                <div className="mono muted" style={{ fontSize: "11px", letterSpacing: "0.12em", marginBottom: "12px" }}>
                  LinkedIn
                </div>
                <h3 className="display-s" style={{ fontSize: "clamp(18px, 1.6vw, 22px)", marginBottom: "12px" }}>
                  {t("contactPage.sections.direct.cards.linkedin.title")}
                </h3>
                <p className="body" style={{ fontSize: "14px" }}>
                  {t("contactPage.sections.direct.cards.linkedin.desc")}
                </p>
                <div style={{ marginTop: "24px" }}>
                  <span className="btn btn-ghost" style={{ display: "inline-flex" }}>
                    LinkedIn <ArrowIcon />
                  </span>
                </div>
              </div>
            </a>
          </div>
        </section>

        {/* ======================================================
            WHAT TO INCLUDE
        ====================================================== */}
        <section className="portfolio-preview shell">
          <div
            className="portfolio-foot"
            style={{ paddingTop: "80px", borderTop: "1px solid var(--rule)" }}
          >
            <div>
              <p className="eyebrow">§ 04 · {t("contactPage.sections.fit.title")}</p>
              <h2 className="display-l reveal" style={{ marginTop: "8px", marginBottom: "32px" }}>
                {t("contactPage.sections.fit.title")}
              </h2>
              <ul style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                {fitItems.map((item, i) => (
                  <li key={item} style={{ display: "flex", gap: "16px", alignItems: "baseline" }}>
                    <span className="mono muted" style={{ fontSize: "11px", flexShrink: 0 }}>
                      {String(i + 1).padStart(2, "0")}
                    </span>
                    <p className="body-lg">{item}</p>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </section>

      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/contact/" : "/en/contact/";
  return (
    <SEO
      data={info}
      titleKey="seo.contact.metaTitle"
      descriptionKey="seo.contact.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={[
        { hrefLang: "fr", href: "https://riano.ca/fr/contact/" },
        { hrefLang: "en", href: "https://riano.ca/en/contact/" },
        { hrefLang: "x-default", href: "https://riano.ca/fr/contact/" },
      ]}
      schemaType="ProfessionalService"
    />
  );
};
